26	    public static final int HOUSEHOLD_MIN = 3;
27	
28	    /** Points awarded once the owner's tenure reaches {@link #TENURE_FISCAL_YEARS} elapsed
29	     *  fiscal years. */
30	    public static final int TENURE_POINTS = 3;
31	
32	    /** The number of elapsed fiscal years the tenure must reach to earn {@link #TENURE_POINTS}. */
33	    public static final int TENURE_FISCAL_YEARS = 1;
