8	/**
9	 * The duplicate block: rejects a create request whose {@link Households#id(OwnerFieldsDto)
10	 * household id} — its last name and postcode — matches an existing owner's, because owners in
11	 * the same household are otherwise indistinguishable at registration. A request may opt out by
12	 * setting {@code sharesHousehold}, declaring it a genuine second member of that household; that
13	 * only bypasses this block, since the household link itself is assigned deterministically
14	 * later (see {@link AssignHousehold}).
15	 */
16	public class EnsureUniqueHousehold {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws HouseholdDuplicateException {
20	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
21	            return;
22	        }
23	        String householdId = Households.id(request);
24	        for (Owner existing : ownerRepository.findAllActive()) {
25	            if (householdId.equals(Households.id(existing))) {
26	                throw new HouseholdDuplicateException(householdId);
27	            }
28	        }
